// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property() public {
        // Call XBornID() which sets balances[owner] = totalDistributed
        // In the reference, totalSupply is unchanged at 500000000e18
        // In the mutant where the totalSupply assignment is removed from burn(), 
        // totalSupply remains 500000000e18 as well, but the bug changes burn() behavior.
        // The property that distinguishes them: after XBornID(), totalSupply must equal 500000000e18.
        // However, the mutant still has the same totalSupply here. 
        // Actually, the difference is that in the reference, totalSupply is mutable and starts at 500000000e18.
        // The mutant removes the line "totalSupply = (totalSupply - (_value));" in burn(), so after burn(), totalSupply stays at original 500000000e18.
        // For the reference, after burn(), totalSupply decreases.
        // So a general rule: totalSupply must always be >= totalDistributed.
        // In reference, after burn, totalSupply - totalDistributed = (500e18 - _value) - (200e18 - _value) = 300e18.
        // In mutant, after burn, totalSupply - totalDistributed = 500e18 - (200e18 - _value) = 300e18 + _value, which can be > totalSupply if _value > 200e18? Actually, totalSupply unchanged, totalDistributed decreases, so difference increases.
        // The property that reference holds: totalSupply >= totalDistributed always.
        // For reference, after XBornID(), totalSupply = 500000000e18, totalDistributed = 200000000e18, holds.
        // For mutant, totalSupply unchanged, totalDistributed decreases by _value, still holds.
        // That's not a distinguishing property.
        // Let's reconsider: The bug removes totalSupply adjustment in burn(), so after burn(), totalSupply reference decreases, mutant does not. So a rule: after calling burn() with some _value, totalSupply must be strictly less than before the call (if _value > 0).
        // But we need to drive through XBornID() first.
        // The sequence: call XBornID(), then call burn(any value). In reference, totalSupply decreases; in mutant, it doesn't.
        // So we can measure totalSupply before burn and after burn, and assert that if _value > 0, then totalSupplyAfter < totalSupplyBefore.
        // Let's implement that.
        c.XBornID();
        uint256 _value = 1e18; // any positive amount less than balances[owner] which is 200000000e18
        // But we need the property to hold for all valid inputs, so we use fuzzing with bound.
        // Actually use fuzz param for _value.
    }
    function testFuzz_property2(uint256 _value) public {
        vm.assume(_value > 0 && _value <= 200000000e18); // owner balance after XBornID() is 200000000e18
        c.XBornID();
        uint256 totalSupplyBefore = c.totalSupply();
        c.burn(_value);
        uint256 totalSupplyAfter = c.totalSupply();
        // In reference, totalSupply decreases. In mutant, it stays same.
        assertTrue(totalSupplyAfter < totalSupplyBefore, "totalSupply should decrease after burn");
    }
}

